    $state=$history['state'];must(is_array($state)&&array_key_exists('pending',$state),'journal_invalid');
    clearstatcache(true,$path);$named=lstat($path);$after=fstat($f);
    foreach(['ino','dev','size','mtime','ctime'] as $k)must(($named[$k]??null)===$stat[$k]&&($after[$k]??null)===$stat[$k],'journal_changed');
    return ['pin'=>$history['pin'],'identity'=>array_intersect_key($stat,array_flip(['ino','dev','size','mtime','ctime'])),
        'pending_null'=>$state['pending']===null,'cycle_terminal'=>cycle_terminal($state),
        'cycle_state'=>$state['nightly_cycle']['state']??null,'cycle_run_id'=>$state['nightly_cycle']['collector_run_id']??null];
